INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Счет УТ-68 от13.10.2026 Трейд Ресурс в загрузку', 'Счёт ООО «Эй Джи Групп» № УТ-68 от 13.10.2026, распознан со скана PDF. Колонки: №, Артикул (текстом, полный — восстановлен по наименованию), Товары, Количество, Ед., Цена, Ставка НДС, Сумма НДС, Сумма. Шапка и подписи убраны, внизу строка «Итого». 46 строк, 54 672 шт, НДС 721 311,47 руб., сумма 4 000 000,00 руб. — сходится со счётом. В строке 14 (MK-666-4) количество × цена = 479 146,05, а сумма в счёте 479 142,00 — так у поставщика.', '/converted/schet-ut-68-13-10-2026-treid-resurs-v-zagruzku.xlsx', 'Счет УТ-68 от13.10.2026 Трейд Ресурс в загрузку.xlsx', 'converted/schet-ut-68-13-10-2026-treid-resurs-v-zagruzku.xlsx', 9840);
INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('Rasprodazha_16_mln сверка с УТ-68', 'Лист «сводная» из Rasprodazha_16_mln без картинок, 46 позиций. Рядом с «Остатки из 1С на 07.10.2026 было» — «Количество из счёта» УТ-68. Парами (было / из счёта) формулами: кол-во единиц на палете, цена за паллет, сумма. Цена — только из файла распродажи. Итого: количество 61 102 → 54 672 шт, сумма 15 356 069,34 → 13 616 680,65 руб.', '/converted/rasprodazha-16-mln-sverka-s-ut-68.xlsx', 'Rasprodazha_16_mln сверка с УТ-68.xlsx', 'converted/rasprodazha-16-mln-sverka-s-ut-68.xlsx', 11086);